create table public.ho_so_giao_vien (ma_ho_so bigint generated always as identity primary key, ma_nguoi_dung uuid not null unique references public.profiles(id), gioi_thieu text not null check (btrim(gioi_thieu) <> ''), kinh_nghiem text not null check (btrim(kinh_nghiem) <> ''), trang_thai varchar(20) not null check (trang_thai in ('CHO_DUYET','DA_DUYET','TU_CHOI')), ly_do_tu_choi text, ngay_gui timestamptz not null default now(), ngay_duyet timestamptz, check (trang_thai <> 'TU_CHOI' or nullif(btrim(ly_do_tu_choi),'') is not null), check (trang_thai = 'CHO_DUYET' or ngay_duyet is not null));
create table public.anh_tac_pham (ma_anh bigint generated always as identity primary key, ma_ho_so bigint not null references public.ho_so_giao_vien, duong_dan_anh varchar(500) not null check (btrim(duong_dan_anh) <> ''), ngay_tai_len timestamptz not null default now());
create table public.thong_bao (ma_thong_bao bigint generated always as identity primary key, ma_nguoi_dung uuid not null references public.profiles(id), loai_thong_bao varchar(50) not null check (btrim(loai_thong_bao) <> ''), noi_dung text not null check (btrim(noi_dung) <> ''), duong_dan_lien_ket varchar(500), da_doc boolean not null default false, ngay_tao timestamptz not null default now());
create table public.khoa_hoc (ma_khoa_hoc bigint generated always as identity primary key, ma_giao_vien uuid not null references public.profiles(id), tieu_de varchar(200) not null check (btrim(tieu_de) <> ''), cap_do varchar(30) not null check (cap_do in ('CO_BAN','TRUNG_CAP','NANG_CAO')), chu_de varchar(100) not null check (btrim(chu_de) <> ''), mo_ta text not null check (btrim(mo_ta) <> ''), anh_dai_dien varchar(500), trang_thai varchar(20) not null check (trang_thai in ('NHAP','CHO_DUYET','DA_DANG','AN','DA_GO')), ngay_tao timestamptz not null default now());
create table public.ghi_danh (ma_nguoi_dung uuid not null references public.profiles(id), ma_khoa_hoc bigint not null references public.khoa_hoc, trang_thai varchar(20) not null check (trang_thai in ('DANG_HOC','HOAN_THANH','DA_HUY')), ngay_ghi_danh timestamptz not null default now(), ngay_hoan_thanh timestamptz, primary key (ma_nguoi_dung,ma_khoa_hoc), check (trang_thai <> 'HOAN_THANH' or ngay_hoan_thanh is not null));
create table public.chuong (ma_chuong bigint generated always as identity primary key, ma_khoa_hoc bigint not null references public.khoa_hoc, tieu_de varchar(200) not null check (btrim(tieu_de) <> ''), thu_tu integer not null check (thu_tu > 0), unique (ma_khoa_hoc,thu_tu));
create table public.bai_hoc (ma_bai_hoc bigint generated always as identity primary key, ma_chuong bigint not null references public.chuong, tieu_de varchar(200) not null check (btrim(tieu_de) <> ''), thu_tu integer not null check (thu_tu > 0), noi_dung_van_ban text, duong_dan_anh varchar(500), lien_ket_video varchar(500), bat_buoc boolean not null default true, unique (ma_chuong,thu_tu));
create table public.tep_dinh_kem_bai_hoc (ma_tep bigint generated always as identity primary key, ma_bai_hoc bigint not null references public.bai_hoc, ten_tep varchar(255) not null check (btrim(ten_tep) <> ''), duong_dan varchar(500) not null check (btrim(duong_dan) <> ''), loai_tep varchar(50) not null check (loai_tep in ('IMAGE','DOCUMENT','REFERENCE')), dung_luong bigint not null check (dung_luong > 0), ngay_tai_len timestamptz not null default now());
create table public.bai_tap (ma_bai_tap bigint generated always as identity primary key, ma_bai_hoc bigint not null references public.bai_hoc, de_bai text not null check (btrim(de_bai) <> ''), han_nop timestamptz, bat_buoc boolean not null default true);
create table public.bai_nop (ma_bai_nop bigint generated always as identity primary key, ma_bai_tap bigint not null references public.bai_tap, ma_nguoi_dung uuid not null references public.profiles(id), duong_dan_anh varchar(500) not null check (btrim(duong_dan_anh) <> ''), trang_thai varchar(20) not null check (trang_thai in ('CHO_CHAM','DA_CHAM')), ngay_nop timestamptz not null default now(), ngay_cap_nhat timestamptz not null default now(), unique (ma_bai_tap,ma_nguoi_dung));
create table public.ket_qua_cham (ma_ket_qua bigint generated always as identity primary key, ma_bai_nop bigint not null unique references public.bai_nop, ma_nguoi_cham uuid not null references public.profiles(id), diem numeric(4,2) not null check (diem between 0 and 10), nhan_xet text not null check (btrim(nhan_xet) <> ''), ngay_cham timestamptz not null default now());
create table public.tien_do_bai_hoc (ma_nguoi_dung uuid not null references public.profiles(id), ma_bai_hoc bigint not null references public.bai_hoc, trang_thai varchar(30) not null check (trang_thai in ('CHUA_HOC','DANG_HOC','DA_HOAN_THANH')), ngay_bat_dau timestamptz, ngay_hoan_thanh timestamptz, primary key (ma_nguoi_dung,ma_bai_hoc), check (trang_thai <> 'DA_HOAN_THANH' or ngay_hoan_thanh is not null));
create table public.lich_su_trang_thai (ma_lich_su bigint generated always as identity primary key, loai_doi_tuong varchar(50) not null check (loai_doi_tuong in ('NGUOI_DUNG','HO_SO_GIAO_VIEN','KHOA_HOC')), ma_doi_tuong varchar(100) not null check (btrim(ma_doi_tuong) <> ''), trang_thai_cu varchar(50), trang_thai_moi varchar(50) not null check (btrim(trang_thai_moi) <> ''), ma_nguoi_thuc_hien uuid not null references public.profiles(id), ly_do text, ngay_thuc_hien timestamptz not null default now());
create index on public.anh_tac_pham (ma_ho_so);
create index on public.thong_bao (ma_nguoi_dung);
create index on public.khoa_hoc (ma_giao_vien);
create index on public.ghi_danh (ma_khoa_hoc);
create index on public.tep_dinh_kem_bai_hoc (ma_bai_hoc);
create index on public.bai_tap (ma_bai_hoc);
create index on public.bai_nop (ma_nguoi_dung);
create index on public.ket_qua_cham (ma_nguoi_cham);
create index on public.tien_do_bai_hoc (ma_bai_hoc);
create index on public.lich_su_trang_thai (ma_nguoi_thuc_hien);
do $$ declare t text; begin foreach t in array array['ho_so_giao_vien','anh_tac_pham','thong_bao','khoa_hoc','ghi_danh','chuong','bai_hoc','tep_dinh_kem_bai_hoc','bai_tap','bai_nop','ket_qua_cham','tien_do_bai_hoc','lich_su_trang_thai'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from public, anon, authenticated',t); end loop; end $$;
